package gr.peptidetracker.app.data

import android.net.Uri

data class Study(val title:String,val source:String,val url:String)
data class PeptideInfo(val id:String,val name:String,val alias:String,val category:String,val status:String,val overview:String,val research:String,val mechanism:String,val warning:String,val studies:List<Study>)
private fun pubmed(q:String)="https://pubmed.ncbi.nlm.nih.gov/?term=${Uri.encode(q)}"
private fun trials(q:String)="https://clinicaltrials.gov/search?term=${Uri.encode(q)}"
private fun p(id:String,name:String,alias:String,category:String,status:String,overview:String,research:String,mechanism:String,warning:String,study:String)=PeptideInfo(id,name,alias,category,status,overview,research,mechanism,warning,listOf(Study(study,"PubMed",pubmed(study)),Study("Καταχωρημένες κλινικές μελέτες","ClinicalTrials.gov",trials(name))))

